const paths={bulb:'M9 18h6M10 21h4M12 3a6 6 0 0 0-3.6 10.8c.8.6 1.1 1.4 1.1 2.2h5c0-.8.3-1.6 1.1-2.2A6 6 0 0 0 12 3z',link:'M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1',undo:'M9 5 4 10l5 5M4 10h10a6 6 0 0 1 0 12',redo:'m15 5 5 5-5 5M20 10H10a6 6 0 0 0 0 12',film:'M3 7h18v14H3zM3 3h18v4H3zM7 3l3 4M14 3l3 4M10 11l5 3-5 3z',calendar:'M4 5h16v16H4zM4 10h16M8 3v4M16 3v4',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 3a4 4 0 0 1 0 8M18 14a4 4 0 0 1 4 4v3',refresh:'M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 3M18 18a8 8 0 0 1-13-3',plus:'M12 5v14M5 12h14',edit:'m4 16 12-12 4 4L8 20H4zM14 6l4 4',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',check:'m4 12 5 5L20 6',left:'m15 5-7 7 7 7',right:'m9 5 7 7-7 7',save:'M4 3h13l3 3v15H4zM8 3v6h8V3M8 21v-8h8v8',close:'m5 5 14 14M5 19 19 5',up:'m5 15 7-7 7 7',down:'m5 9 7 7 7-7',archive:'M3 4h18v4H3zM5 8v12h14V8M10 12h4',retake:'M3 12a9 9 0 1 0 3-6.7M3 4v5h5'};
