const btn=(label,action,cl='',extra='')=>`<button class="${cl}" data-action="${action}" ${extra}>${label}</button>`;
const ib=(n,label,action,extra='')=>btn(icon(n),action,'icon',`title="${esc(label)}" aria-label="${esc(label)}" ${extra}`);
let db,state={session:null,items:[],dirty:[],conflicts:{}},view='ideas',selected='',tab='script',indices={},shoot=null,syncing=false,message='',busy=false;
let persistChain=Promise.resolve(),wakeLock=null,syncRun=Promise.resolve();
// hypo — open hypothesis; sheet — the card `selected` is shown in a window over the current screen.
let hypo='',sheet=false;
// Accounts (28.10.2026): several sessions on one phone — owner, own profile, owner's cabinet as editor,
// owner's visit into a profile. The active one lives under 'workspace', the others under 'ws:<key>'.
let accounts=[],loginOpen=false,pendingInvite='',resumeHidden=false;
const RESUME_KEY='shooting-resume';
function accountKey(s){return s.role==='owner'?'owner':s.role==='visit'?'visit:'+(s.profile||s.id):s.id}
function accountLabel(s){return s.role==='owner'?'Мои сценарии · владелец':s.role==='visit'?`Профиль «${s.name}» · вход владельца`:s.role==='author'?`Свой профиль · ${s.name}`:`Кабинет владельца · ${s.name}`}
function chipLabel(s){return s.role==='owner'?'Мои':s.role==='visit'?s.name:s.role==='author'?'Мой профиль':'Кабинет'}
function roleLabel(s){return {owner:'Владелец',author:'Свой профиль',visit:'Вход владельца в профиль'}[s.role]||'Кабинет владельца'}
function standalone(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
function idb(mode,fn){return new Promise((resolve,reject)=>{const tr=db.transaction('state',mode),r=fn(tr.objectStore('state'));tr.oncomplete=()=>resolve(r.result);tr.onerror=()=>reject(tr.error);tr.onabort=()=>reject(tr.error)})}
const idbGet=k=>idb('readonly',s=>s.get(k)),idbPut=(k,v)=>idb('readwrite',s=>s.put(v,k)),idbDel=k=>idb('readwrite',s=>s.delete(k));
async function saveAccounts(){if(state.session){const key=accountKey(state.session),i=accounts.findIndex(a=>a.key===key),a={key,session:copy(state.session)};if(i>=0)accounts[i]=a;else accounts.push(a)}await idbPut('accounts',copy(accounts))}
async function openAccount(session,saved){if(syncing)await Promise.race([syncRun,new Promise(r=>setTimeout(r,8000))]);const key=accountKey(session),cur=state.session&&accountKey(state.session);loginOpen=false;pendingInvite='';
 if(cur!==key){if(cur){await persistChain;await idbPut('ws:'+cur,copy(state))}saved??=await idbGet('ws:'+key);state=saved||{session,items:[],dirty:[],conflicts:{}};view='ideas';selected='';sheet=false;hypo='';resumeHidden=false}
 state.session=session;await persist();await saveAccounts();render();void sync()}
async function switchAccount(key){const a=accounts.find(x=>x.key===key);if(!a||state.session&&accountKey(state.session)===key){render();return}if(state.dirty.length&&!syncing)await sync();if(syncing)await Promise.race([syncRun,new Promise(r=>setTimeout(r,8000))]);const saved=await idbGet('ws:'+key);await openAccount(saved?.session||a.session,saved)}
function loginExtras(invite){const others=accounts.filter(a=>!state.session||a.key!==accountKey(state.session));return `${invite?btn('Войти по PIN владельца','login-pin','quiet'):''}${others.length?`<div class="login-accounts"><div class="section-caption">Уже входили на этом устройстве</div>${others.map(a=>btn(esc(accountLabel(a.session)),'switch-account','',`data-key="${esc(a.key)}"`)).join('')}</div>`:''}${state.session?btn('Отмена','login-cancel','quiet'):''}`}
// Interrupted filming: the place is remembered per account; if storage was wiped, a started day is found from the data.
function saveResume(){const r=shoot&&item(shoot.ids[shoot.card]);if(r&&state.session)writeLocal(RESUME_KEY+':'+accountKey(state.session),{day:shoot.day,card:r.id,step:shoot.step,at:Date.now()})}
function started(c){return c.slate||variants(c).some(v=>v.filmed)}
function resumePoint(){if(!state.session)return null;const s=readLocal(RESUME_KEY+':'+accountKey(state.session),null),fresh=s&&Date.now()-s.at<3*864e5&&item(s.day)?.kind==='day'&&!item(s.day).data.archived;
 const day=fresh?s.day:days().find(d=>{const c=cards(d.id);return c.some(r=>started(r.data))&&c.some(r=>!complete(r.data))})?.id;if(!day)return null;
 const rest=cards(day).filter(r=>!complete(r.data));if(!rest.length)return null;const card=(fresh&&rest.find(r=>r.id===s.card))||rest.find(r=>started(r.data))||rest[0];
 if(!fresh&&!started(card.data))return null;return {day,card:card.id,step:fresh&&s.card===card.id?s.step:null}}
function resumeBanner(){const p=!resumeHidden&&resumePoint();if(!p)return '';const r=item(p.card),steps=shootSteps(r.data),i=p.step!=null&&steps[p.step]&&!steps[p.step].filmed?p.step:Math.max(0,steps.findIndex(x=>!x.filmed));return `<div class="resume-banner">${icon('film')}<div class="resume-text"><b>Съёмка прервалась</b><span>${esc(item(p.day).data.title)} · ${esc(r.data.spoken_code||r.data.code)} · фраза ${i+1} из ${steps.length}</span></div>${btn('Продолжить','resume-shoot','primary')}${ib('close','Скрыть','resume-hide')}</div>`}
async function startShoot(day,cardId,step){const remaining=cards(day).filter(x=>!complete(x.data));if(!remaining.length){notify('Все карточки сняты. Открой сценарий для просмотра.');return}selected=day;sheet=false;const i=Math.max(0,remaining.findIndex(x=>x.id===cardId));shoot={day,ids:remaining.map(x=>x.id),card:i,step:0};const steps=shootSteps(remaining[i].data),first=steps.findIndex(x=>!x.filmed);shoot.step=step!=null&&steps[step]&&!steps[step].filmed?step:Math.max(0,first);render();try{wakeLock=await navigator.wakeLock?.request('screen')}catch{}}
const VIEW_KEY='shooting-ideas-view',THEME_KEY='shooting-theme',STAGES=[['work','В работе'],['written','Написанные'],['filmed','Снятые']];
const readLocal=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},writeLocal=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
let ideaView={show:{work:true,written:true,filmed:true},sort:'new',...readLocal(VIEW_KEY,{})},ideaQuery='';
function themePref(){const t=readLocal(THEME_KEY,'system');return ['light','dark'].includes(t)?t:'system'}
function applyTheme(){const t=themePref(),root=document.documentElement;if(t==='system')delete root.dataset.theme;else root.dataset.theme=t;const dark=t==='dark'||(t==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.querySelector('meta[name=theme-color]')?.setAttribute('content',dark?'#12171b':'#f0f3f5')}
applyTheme();matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',applyTheme);
let requestedCard=new URLSearchParams(location.search).get('card');
async function openDB(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('shooting-private-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const stored=await new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(stored)state=stored;accounts=(await idbGet('accounts'))||[];if(state.session&&!accounts.some(a=>a.key===accountKey(state.session)))await saveAccounts();}
function persist(){const snapshot=copy(state);persistChain=persistChain.then(()=>new Promise((resolve,reject)=>{const t=db.transaction('state','readwrite');t.objectStore('state').put(snapshot,'workspace');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)}));return persistChain;}
function notify(t){$('#notice').textContent=t;$('#notice').style.display='block';setTimeout(()=>$('#notice').style.display='none',4500)}
async function api(path,body,method=body?'POST':'GET',token=state.session?.token){const r=await fetch(API+path,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store',referrerPolicy:'no-referrer'});const d=await r.json();if(!r.ok){const e=new Error(typeof d.detail==='string'?d.detail:'Сервер не принял изменения');e.status=r.status;e.detail=d.detail;throw e}return d;}
function item(id=selected){return state.items.find(i=>i.id===id)}
function can(f){return (state.features||[]).includes(f)}
function cards(day){return state.items.filter(i=>i.kind==='card'&&!i.data.archived&&(day===undefined||i.data.day_id===day)).sort((a,b)=>a.data.order-b.data.order)}
function days(){return state.items.filter(i=>i.kind==='day'&&!i.data.archived)}
function variants(c){return c.blocks.flatMap(b=>b.variants.filter(v=>v.text.trim()).map(v=>({...v,block:b.title,blockId:b.id})));}
function spoken(c){return variants(c).filter(v=>v.block!=='Заметки себе')}
function complete(c){const v=spoken(c);return c.slate&&v.length>0&&v.every(x=>x.filmed)}
function progress(c){const writing=c.blocks.filter(b=>b.title!=='Заметки себе');const filled=writing.filter(b=>b.variants.some(v=>v.text.trim())&&b.variants.filter(v=>v.text.trim()).every(v=>v.origin==='manual'||v.reviewed)).length;const v=spoken(c);const platforms=Object.values(c.details.platforms);return [writing.length?filled/writing.length:0,v.length?(v.filter(x=>x.filmed).length+Number(c.slate))/(v.length+1):0,['color','edit','subtitles'].filter(k=>c.details[k]).length/3,platforms.length?platforms.filter(Boolean).length/platforms.length:0]}
function bars(c){return `<div class="progress">${progress(c).map((v,i)=>`<div><small>${['Написание','Съёмка','Постпрод','Постинг'][i]}</small><progress max="1" value="${v}" aria-label="${['Написание','Съёмка','Постпрод','Постинг'][i]}"></progress><small>${Math.round(v*100)}%</small></div>`).join('')}</div>`}
async function change(id,fn,remember=true){const r=item(id);if(!r)return;if(remember&&r.kind==='card'){state.history??={};const h=state.history[id]??={undo:[],redo:[]};h.undo.push({data:copy(r.data),drafts:copy(Object.values(state.drafts||{}).filter(d=>d.card===id))});h.undo=h.undo.slice(-30);h.redo=[]}fn(r.data);r.localVersion=(r.localVersion||0)+1;if(!state.dirty.includes(id))state.dirty.push(id);await persist();render();void sync();}
async function add(kind,data,id=uid()){state.items.push({id,kind,data,revision:0,localVersion:1,created:new Date().toISOString()});state.dirty.push(id);await persist();void sync();return id;}
// A sync belongs to the account it started in: switching mid-sync must not pour that account's cards into the next one.
async function sync(){if(syncing||!state.session||!navigator.onLine)return;const st=state,token=st.session.token,own=id=>st.items.find(i=>i.id===id),save=()=>state===st?persist():idbPut('ws:'+accountKey(st.session),copy(st));syncing=true;let done;syncRun=new Promise(r=>done=r);message='Синхронизация…';status();try{
 for(const id of [...st.dirty]){if(st.conflicts[id])continue;const r=own(id);if(!r)continue;const snapshot=copy(r);try{const saved=await api('/shooting/items/'+id,{kind:r.kind,revision:r.revision,data:snapshot.data},'PUT',token);const current=own(id);if(!current)continue;current.revision=saved.revision;if(current.localVersion===snapshot.localVersion){current.data=saved.data;st.dirty=st.dirty.filter(x=>x!==id)}}catch(e){if(e.status===409){st.conflicts[id]=e.detail?.current||{message:e.message};continue}
  // 404: the card lives in another account's workspace (copied here by the old switching bug) and can never be saved from this one.
  if(e.status===404&&r.revision>0){st.dirty=st.dirty.filter(x=>x!==id);st.items=st.items.filter(x=>x.id!==id);continue}throw e}await save();}
 const remote=await api('/shooting/workspace',undefined,'GET',token);if(state!==st){await save();return}state.features=remote.features||[];const ids=new Set(remote.items.map(r=>r.id));state.items=state.items.filter(r=>ids.has(r.id)||state.dirty.includes(r.id)||!(r.revision>0));for(const r of remote.items){const local=item(r.id);if(!local)state.items.push(r);else if(!state.dirty.includes(r.id)&&!((r.id===selected&&document.querySelector('dialog[open],textarea:focus,input:focus,select:focus'))||Object.values(state.drafts||{}).some(d=>d.card===r.id)))Object.assign(local,r)}await persist();if(requestedCard&&item(requestedCard)){selected=requestedCard;view='card';tab='script';requestedCard=null;}message=Object.keys(state.conflicts).length?'Есть изменения для сверки':state.dirty.length?'Есть локальные изменения':'Всё сохранено';
 }catch(e){if(state!==st)return;message=e.status===401?'Сеанс истёк — войди заново':e.status===422?e.message+' · правки на устройстве':navigator.onLine?'Нет связи с сервером · изменения на устройстве':'Без интернета · изменения на устройстве';}finally{syncing=false;done();if(state!==st){void sync();return}status();if(!document.querySelector('textarea:focus,input:focus,select:focus,dialog[open]')&&!shoot)render();else if(view==='hypothesis'&&!sheet&&$('#themes'))refreshThemes();}}
function status(){document.querySelectorAll('.sync').forEach(e=>e.textContent=message||(!navigator.onLine?'Без интернета':state.dirty.length?'Изменения на устройстве':'Всё сохранено'))}
function shell(content){const active=view==='card'?'ideas':view==='day'?'days':view==='hypothesis'?'hypotheses':view;return `<div class="shell"><header class="top"><div class="identity"><span class="brand-mark">${icon('film')}</span><div><div class="brand">Съёмки</div><div class="brand-caption">Твоя редакционная мастерская</div></div></div><div class="header-status">${state.session?btn(`${icon('users')}<span>${esc(chipLabel(state.session))}</span>`,'accounts','account-chip',`title="${esc(accountLabel(state.session))}" aria-label="Аккаунт: ${esc(accountLabel(state.session))}"`):''}<div class="sync"></div>${ib('refresh','Обновить','sync')}</div></header><nav class="main-nav" aria-label="Разделы приложения">${[['ideas','Идеи','film'],['days','Съёмочные дни','calendar'],...(can('hypotheses')?[['hypotheses','Гипотезы','bulb']]:[]),['settings','Доступ','users']].map(([v,t,i])=>btn(icon(i)+`<span>${t}</span>`,'nav',active===v?'active':'',`data-view="${v}" ${active===v?'aria-current="page"':''}`)).join('')}</nav><div class="page-content">${content}</div></div>`}

function localCode(){let code;do{code='L-'+(1000+crypto.getRandomValues(new Uint32Array(1))[0]%9000)}while(state.items.some(r=>r.data.code===code));return code}
function stage(c){return complete(c)?'filmed':progress(c)[0]>=1?'written':'work'}
function addedAt(r){return Date.parse(r.created||r.updated||'')||Date.now()}
function archived(){return state.items.filter(i=>i.kind==='card'&&i.data.archived)}
function ideaCards(){const q=ideaQuery.trim().toLowerCase(),h=hypFilter();return (ideaView.archive?archived():cards()).filter(r=>(ideaView.archive||ideaView.show[stage(r.data)]!==false)&&(!h||(h==='-'?!r.data.hypothesis_id:r.data.hypothesis_id===h))&&(!q||(r.data.title+' '+r.data.idea+' '+r.data.code+' '+(r.data.spoken_code||'')).toLowerCase().includes(q))).sort((a,b)=>ideaView.sort==='old'?addedAt(a)-addedAt(b):addedAt(b)-addedAt(a))}
function ideasGrid(){if(ideaView.archive)return ideaCards().map(cardTile).join('')||'<div class="empty">'+(archived().length?'В архиве ничего не нашлось.':'Архив пуст. Убрать идею сюда можно кнопкой на её карточке.')+'</div>';if(!cards().length)return '<div class="empty">Первая идея — начало следующего видео.</div>';return ideaCards().map(cardTile).join('')||'<div class="empty">Под выбранные фильтры ничего не подходит.</div>'}
function ideaFilters(){const all=cards(),n={work:0,written:0,filmed:0};for(const r of all)n[stage(r.data)]++;return `<div class="idea-filters">${STAGES.map(([k,t])=>btn(`<span>${t}</span><span class="n">${n[k]}</span>`,'idea-filter','chip',`data-key="${k}" aria-pressed="${ideaView.show[k]!==false}" ${ideaView.archive?'disabled':''}`)).join('')}${btn(`<span>Архив</span><span class="n">${archived().length}</span>`,'idea-archive','chip chip-archive',`aria-pressed="${!!ideaView.archive}"`)}${hypSelect()}<select id="idea-sort" class="idea-sort" aria-label="Сортировка"><option value="new" ${ideaView.sort!=='old'?'selected':''}>Сначала новые</option><option value="old" ${ideaView.sort==='old'?'selected':''}>Сначала старые</option></select></div>`}
function cardTile(r){const c=r.data;return `<article class="card"><div class="row between"><span class="code">${esc(c.spoken_code||c.code)}</span><span class="pill">${c.archived?'В архиве':complete(c)?'Снято':c.day_id?esc(item(c.day_id)?.data.title||'День'):'Без съёмочного дня'}</span></div>${btn(`<h3>${esc(c.title)}</h3>`,'open','open',`data-id="${r.id}"`)}${hypName(c)?`<div class="tile-hyp">${icon('bulb')}<span>${esc(hypName(c))}</span></div>`:''}${bars(c)}<div class="muted">Перформанс — статистика появится позже</div><div class="row tile-actions">${btn('Открыть сценарий','open','',`data-id="${r.id}"`)}${c.archived?btn('Вернуть','unarchive','',`data-id="${r.id}"`):ib('archive','Убрать в архив','archive',`data-id="${r.id}"`)}</div></article>`}
let shown='',scrolls={};
function render(){if(shoot){renderShoot();return}if(!state.session){renderLogin();return}if(loginOpen)return;let html='';
 if(view==='ideas'){html=`<div class="eyebrow">От мысли до публикации</div><div class="row between"><h1>Банк идей</h1>${btn('Новая идея','new-card','primary')}</div><p class="muted">Отправляй идеи из завода или записывай свои. Сценарии и отметки доступны без интернета после загрузки.</p><input id="search" placeholder="Найти идею или код" aria-label="Поиск идеи" value="${esc(ideaQuery)}">${ideaFilters()}<div class="grid" id="cards" style="margin-top:20px">${ideasGrid()}</div>`;}
 else if(view==='days'){html=`<div class="eyebrow">План съёмок</div><div class="row between"><h1>Съёмочные дни</h1>${btn('Добавить день','new-day','primary')}</div><p class="muted">Собери идеи в день, проверь сценарии и нажми «Съёмка». Приложение проведёт по всем вариантам фраз.</p><div class="grid">${days().map(d=>{const c=cards(d.id),n=c.filter(r=>complete(r.data)).length;return `<article class="card"><h2>${esc(d.data.title)}</h2><p class="muted">${esc(d.data.date||'Дата не назначена')}</p><progress value="${n}" max="${c.length||1}"></progress><p>${n} из ${c.length} карточек снято</p><div class="row">${btn('Открыть день','day','',`data-id="${d.id}"`)}${n<c.length&&c.some(r=>started(r.data))?btn('Продолжить съёмку','shoot-day','primary',`data-id="${d.id}"`):''}</div></article>`}).join('')||'<div class="empty">Создай «День 1» и добавь в него идеи.</div>'}</div>`;}
 else if(view==='day'){const d=item(),c=cards(d.id),n=c.filter(r=>complete(r.data)).length;html=`${btn('Все дни','nav','', 'data-view="days"')}<h1>${esc(d.data.title)}</h1><div class="row">${btn('Название и дата','edit-day')}${btn('Добавить идеи','assign')}</div><progress value="${n}" max="${c.length||1}"></progress><p class="muted">Снято ${n} из ${c.length} · порядок можно менять стрелками</p>${c.map((r,i)=>`<div class="panel"><div class="row between"><div><span class="code">${esc(r.data.spoken_code||r.data.code)}</span><h3>${esc(r.data.title)}</h3></div><div class="row">${ib('up','Выше','reorder',`data-id="${r.id}" data-dir="-1" ${i===0?'disabled':''}`)}${ib('down','Ниже','reorder',`data-id="${r.id}" data-dir="1" ${i===c.length-1?'disabled':''}`)}</div></div>${bars(r.data)}${btn('Сценарий и детали','open','',`data-id="${r.id}"`)}</div>`).join('')}<div class="sticky-action">${btn(n===c.length&&c.length?'Всё снято · посмотреть':c.some(r=>started(r.data))?'Продолжить съёмку':'Съёмка','shoot','primary',c.length?'':'disabled')}</div>`;}
 else if(view==='card')html=renderCard();
 else if(view==='hypotheses')html=renderHypotheses();
 else if(view==='hypothesis'){if(!item(hypo)){view='hypotheses';html=renderHypotheses()}else html=renderHypothesis()}
 else if(view==='settings'){html=`<div class="eyebrow">Рабочее пространство</div><h1>Доступ и устройство</h1><p class="page-intro">Всё для совместной работы и съёмок без интернета.</p><div class="settings-layout ${state.session.role==='owner'?'':'solo'}"><section class="panel account-panel"><div class="section-caption">Твой профиль</div><div class="profile-row"><div class="avatar">${esc(state.session.name.slice(0,1))}</div><div><h2>${esc(state.session.name)}</h2><span class="pill">${roleLabel(state.session)}</span></div></div><p class="muted">Доступ к идеям, сценариям и съёмочным дням.</p><div class="row settings-actions">${btn('Сменить или добавить аккаунт','accounts','primary')}${btn('Войти заново','reauth')}${btn('Выйти из этого аккаунта','logout','quiet')}</div></section><section class="panel device-panel"><div class="section-caption">Всегда под рукой</div><h2>Установи на телефон</h2><ol class="install-steps"><li><span>1</span><div>Открой в Safari<p>На iPhone нажми «Поделиться» → «На экран Домой».</p></div></li><li><span>2</span><div>Подготовься к съёмке<p>Открой нужные карточки с интернетом и дождись «Всё сохранено».</p></div></li><li><span>3</span><div>Снимай без связи<p>Сценарии и отметки останутся на телефоне. Изменения синхронизируются при подключении.</p></div></li></ol><div class="theme-block"><div class="section-caption">Тема на этом устройстве</div><div class="tabs theme-switch" role="group" aria-label="Тема">${[['system','Как в системе'],['light','Светлая'],['dark','Тёмная']].map(([k,t])=>btn(t,'theme',themePref()===k?'active':'',`data-theme-pick="${k}" aria-pressed="${themePref()===k}"`)).join('')}</div></div></section>${state.session.role==='owner'?`<section class="panel team-panel"><div class="section-caption">Совместная работа</div><div class="team-illustration" aria-hidden="true">${icon('users')}</div><h2>Пригласи в свой кабинет</h2><p class="muted">Монтажёр или помощник видит и правит твои сценарии, исходники и этапы готовности. Если у человека уже есть свой профиль, после входа по ссылке на его телефоне будут оба аккаунта.</p><div class="team-benefits"><div>${icon('check')}Сценарии и варианты фраз</div><div>${icon('check')}Монтаж, цвет и субтитры</div><div>${icon('check')}Ссылки на опубликованные видео</div></div><div class="row settings-actions">${btn('Создать приглашение','invite','primary')}${btn('Список доступов','members')}</div>${can('profiles')?`<div class="profile-block"><div class="section-caption">Отдельный профиль</div><p class="muted">Для того, кто пишет свои сценарии: свои идеи, кадры и съёмочные дни, отдельно от твоих.</p>${btn('Создать профиль','new-profile')}</div>`:''}<details class="access-help"><summary>Как работает приглашение</summary><p>Одноразовая ссылка действует 48 часов. После входа доступ действует 90 дней. Его можно отозвать в списке доступов. Скачанные данные на чужом устройстве удалённо не стираются.</p></details><div id="members"></div></section>`:''}</div><footer class="version">Съёмки · версия 15</footer>`;}

 if(Object.keys(state.conflicts).length)html=`<div class="error">Изменения пересеклись с правками на другом устройстве. Обе версии сохранены. ${btn('Разобрать версии','conflicts')}</div>`+html;
 if(['ideas','days','day','hypotheses'].includes(view))html=resumeBanner()+html;
 const y0=scrollY,old=$('#sheet'),sheetY=old?.dataset.card===selected?old.scrollTop:0;if(sheet&&!item())sheet=false;$('#app').innerHTML=shell(html)+(sheet?`<div class="sheet" id="sheet" data-card="${selected}" role="dialog" aria-modal="true" aria-label="Карточка темы"><div class="sheet-body">${renderCard(true)}</div></div>`:'');document.body.classList.toggle('sheet-open',sheet);if(sheet)$('#sheet').scrollTop=sheetY;status();if(view==='ideas'){$('#search').addEventListener('input',e=>{ideaQuery=e.target.value;$('#cards').innerHTML=ideasGrid()});$('#idea-sort').addEventListener('change',e=>{ideaView.sort=e.target.value;writeLocal(VIEW_KEY,ideaView);$('#cards').innerHTML=ideasGrid()});$('#idea-hyp')?.addEventListener('change',e=>{ideaView.hyp=e.target.value;writeLocal(VIEW_KEY,ideaView);$('#cards').innerHTML=ideasGrid()})}bindSwipes();fitTexts();const key=view+':'+(view==='hypothesis'?hypo:sheet?'':selected);if(key!==shown){scrolls[shown]=y0;shown=key;scrollTo(0,view==='card'?0:scrolls[key]||0)}}
// Block texts are as tall as their content; three lines when empty (min-height in CSS).
function fitText(t){t.style.height='auto';t.style.height=t.scrollHeight+t.offsetHeight-t.clientHeight+'px'}
function fitTexts(){document.querySelectorAll('.inline-phrase').forEach(fitText)}
function scriptText(r){const c=r.data,lines=[c.title,'Код: '+(c.spoken_code||c.code),'','Идея',c.idea||''];let hasDraft=false;
 for(const b of c.blocks){const drafts=Object.values(state.drafts||{}).filter(d=>d.card===r.id&&d.block===b.id),variants=[...b.variants,...drafts.filter(d=>d.isNew&&!b.variants.some(v=>v.id===d.variant)).map(d=>({id:d.variant,text:''}))];const texts=variants.map(v=>{const draft=drafts.find(d=>d.variant===v.id);if(draft)hasDraft=true;return {text:(draft?.text??v.text).trim(),draft:!!draft}}).filter(v=>v.text);if(!texts.length)continue;lines.push('',b.title);texts.forEach((v,i)=>lines.push((texts.length>1?'Вариант '+(i+1):'Текст')+(v.draft?' · черновик':''),v.text,''))}
 if(hasDraft)lines.push('В экспорт включены текущие черновики с этого устройства.');return lines.join('\n').trim()+'\n';}
function exportScript(r){const text=scriptText(r),blob=new Blob(['\uFEFF',text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=((r.data.spoken_code||r.data.code)+' — '+r.data.title).replace(/[<>:"/\\|?*\x00-\x1f]/g,'-').slice(0,100)+'.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Сценарий экспортирован в текстовый файл');}
function renderCard(inSheet=false){const c=item().data,h=state.history?.[selected];return `${inSheet?`<div class="sheet-top">${btn('Закрыть','sheet-close','primary')}${hypName(c)?`<span class="muted">${esc(hypName(c))}</span>`:''}</div>`:btn('К идеям','nav','','data-view="ideas"')}<div class="row between" style="margin-top:22px"><span class="code">${esc(c.spoken_code||c.code)}</span><div class="row">${btn('Дублировать','duplicate')}${btn('Экспорт .txt','export-script')}${btn('Название и идея','edit-idea')}</div></div><h1>${esc(c.title)}</h1><div class="row card-history">${ib('undo','Отменить сохранённое изменение','undo-card',!h?.undo.length?'disabled':'')}${ib('redo','Повторить изменение','redo-card',!h?.redo.length?'disabled':'')}${btn('Сбросить съёмку','reset-shoot','',filmedAny(c)?'':'disabled')}${btn('Сбросить карточку','reset-card','quiet')}<span class="muted">Отмена и повтор сохранённых изменений</span></div>${bars(c)}<div class="tabs">${btn('Сценарий','tab',tab==='script'?'active':'','data-tab="script"')}${btn('Детали','tab',tab==='details'?'active':'','data-tab="details"')}</div>${tab==='details'?details(c):`<div class="panel"><p>${esc(c.idea)}</p>${c.source_title?`<p class="muted">Источник: ${esc(c.source_title)} · ${esc(c.timecode)}</p>`:''}<p class="hint">Три независимых способа: пиши вручную, добавляй цитаты из лекции или черновики ИИ. Новые варианты добавляются к существующим.</p><div class="row">${btn('Текст из лекции','fill','','data-mode="quote"')}${btn('Написать с ИИ','fill','','data-mode="ai"')}</div></div>${c.blocks.map((b,i)=>block(b,i)).join('')}${btn('Добавить блок','add-block')}<p class="muted">При изменении текста отметка съёмки этого варианта сбрасывается. Варианты ИИ требуют просмотра.</p>`}`;}
function filmedAny(c){return c.slate||c.blocks.some(b=>b.variants.some(v=>v.filmed))}
function draftKey(bid,vid){return selected+':'+bid+':'+vid}
function blockVariants(b){const extra=Object.values(state.drafts||{}).filter(d=>d.card===selected&&d.block===b.id&&d.isNew);return [...b.variants,...extra.filter(d=>!b.variants.some(v=>v.id===d.variant)).map(d=>({id:d.variant,text:'',origin:'manual',isNew:true}))]}
function block(b,i){let vs=blockVariants(b);if(!vs.length)vs=[{id:'new-'+b.id,text:'',origin:'manual',isNew:true}];const ix=Math.min(indices[b.id]||0,vs.length-1);indices[b.id]=ix;return `<section class="block" data-block="${b.id}"><div class="row between"><h2>${esc(b.title)}</h2><div class="tools">${ib('up','Переместить блок выше','block-up',`data-block="${b.id}" ${i===0?'disabled':''}`)}${ib('trash','Удалить весь блок','del-block',`data-block="${b.id}"`)}</div></div><div class="variant-rail" data-rail="${b.id}" aria-label="Варианты: ${esc(b.title)}">${vs.map((v,n)=>{const draft=state.drafts?.[draftKey(b.id,v.id)];return `<article class="variant-page" data-variant-page="${v.id}"><div class="meta">${v.isNew?'Новый вариант':`Вариант ${n+1} · ${{manual:'Твой текст',quote:'Цитата из лекции',ai:'Черновик ИИ'}[v.origin]}${v.filmed?' · Снято':''}`}</div><textarea class="inline-phrase" aria-label="${esc(b.title)} — вариант ${n+1}" data-inline-block="${b.id}" data-inline-variant="${v.id}" data-new="${v.isNew?'1':''}" maxlength="12000" placeholder="Нажми и напиши текст…">${esc(draft?.text??v.text)}</textarea><div class="row between"><span class="draft-status" aria-live="polite">${draft?'Черновик на устройстве':' '}</span><div class="tools">${ib('save','Сохранить текст','save-variant',`data-block="${b.id}" data-variant="${v.id}"`)}${draft&&!v.isNew?ib('undo','Отменить правки','cancel-variant',`data-block="${b.id}" data-variant="${v.id}"`):''}${ib('close',v.isNew?'Убрать черновик':'Удалить этот вариант','x-variant',`data-block="${b.id}" data-variant="${v.id}"`)}</div></div>${!v.isNew&&v.origin!=='manual'&&!v.reviewed?btn('Проверено мной','review','','data-block="'+b.id+'" data-variant="'+v.id+'"'):''}</article>`}).join('')}</div><div class="row between variant-navigation"><div class="row">${ib('left','Предыдущий вариант','variant',`data-block="${b.id}" data-dir="-1"`)}<span class="variant-count">${ix+1} / ${vs.length}</span>${ib('right','Следующий вариант','variant',`data-block="${b.id}" data-dir="1"`)}</div><div class="tools">${ib('plus','Ещё вариант','add-variant',`data-block="${b.id}"`)}</div></div>${vs.length>1?'<p class="swipe-hint">Листай варианты влево и вправо</p>':''}</section>`}
function details(c){return `<section class="panel"><h2>Организация</h2>${can('hypotheses')?`<label>Гипотеза<select data-field="hypothesis_id"><option value="">Без гипотезы</option>${hyps().map(h=>`<option value="${h.id}" ${c.hypothesis_id===h.id?'selected':''}>${esc(h.data.title)}</option>`).join('')}</select></label>`:''}<label>Съёмочный день<select data-field="day_id"><option value="">Без дня</option>${days().map(d=>`<option value="${d.id}" ${c.day_id===d.id?'selected':''}>${esc(d.data.title)}</option>`).join('')}</select></label><label>Дата съёмки<input type="date" data-detail="filmed_at" value="${esc(c.details.filmed_at)}"></label><label>Где лежат исходники<textarea data-detail="raw_files" placeholder="Папка, ссылка на диск, имена файлов">${esc(c.details.raw_files)}</textarea></label><p class="muted">Код для камеры: ${esc(c.spoken_code||c.code)}. Исходный код: ${esc(c.code)} — по нему тоже можно найти карточку. Файлы здесь не загружаются — сохраняется их расположение.</p><h2>Постпрод</h2>${[['color','Цвет'],['edit','Монтаж'],['subtitles','Субтитры']].map(([k,t])=>`<label class="check"><input type="checkbox" data-detail="${k}" ${c.details[k]?'checked':''}>${t}</label>`).join('')}<h2>Постинг</h2><p class="muted">Отметь нужные площадки. Ссылка на публикацию завершает этап для этой площадки.</p>${Object.entries(PLAT).map(([k,t])=>`<label class="check"><input type="checkbox" data-platform="${k}" ${k in c.details.platforms?'checked':''}>${t}</label>${k in c.details.platforms?`<input type="url" data-link="${k}" aria-label="Ссылка ${t}" placeholder="https://…" value="${esc(c.details.platforms[k])}">`:''}`).join('')}<label>Заметки для монтажёра<textarea data-detail="notes">${esc(c.details.notes)}</textarea></label><h2>Перформанс</h2><p class="muted">Статистика публикаций появится здесь позже.</p></section>`;}
function modal(html){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=html;document.body.append(d);d.showModal();return d;}
function editor(title,value,onSave,multiline=true){const d=modal(`<h2>${esc(title)}</h2><form><label>${esc(title)}${multiline?`<textarea required maxlength="12000" autofocus>${esc(value)}</textarea>`:`<input required maxlength="200" value="${esc(value)}" autofocus>`}</label><div class="row">${ib('save','Сохранить','noop','type="submit"')}${btn('Отмена','close','','type="button"')}</div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const v=d.querySelector('textarea,input').value.trim();if(!v||d.dataset.saving)return;d.dataset.saving='1';try{await onSave(v);d.close();d.remove();render()}catch(err){notify(err.message)}finally{delete d.dataset.saving}};const field=d.querySelector('textarea,input');field.focus({preventScroll:true});field.setSelectionRange(field.value.length,field.value.length);}
function renderLogin(){const invite=new URLSearchParams(location.hash.slice(1)).get('invite')||pendingInvite;pendingInvite=invite||'';loginOpen=!!state.session;$('#app').innerHTML=`<main class="login"><img class="app-mark" src="icon-192.png?v=6" alt=""><div class="eyebrow">Идеи. Камера. Действие.</div><h1>Съёмки<span style="color:var(--accent)">.</span></h1><p>Твои сценарии и съёмочные дни — под рукой, даже без интернета.</p><form id="login"><label>${invite?'Одноразовое приглашение':'PIN владельца'}<input id="credential" inputmode="${invite?"text":"numeric"}" maxlength="${invite?512:64}" type="${invite?'text':'password'}" autocomplete="${invite?'off':'current-password'}" required value="${esc(invite||'')}"></label>${invite?'':`<div class="pin-pad" role="group" aria-label="Клавиатура PIN">${['1','2','3','4','5','6','7','8','9','clear','0','back'].map(k=>`<button type="button" data-pin="${k}" aria-label="${k==='clear'?'Очистить PIN':k==='back'?'Удалить последнюю цифру':k}">${k==='clear'?'C':k==='back'?'⌫':k}</button>`).join('')}</div>`}<button type="submit" class="primary">${invite?'Принять приглашение':'Войти'}</button></form><p class="muted">Монтажёр и отдельные профили входят по ссылке владельца.</p>${loginExtras(invite)}<p id="login-error" role="alert"></p></main>`;if(invite)history.replaceState(null,'',location.pathname+location.search);document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>{const input=$('#credential'),k=b.dataset.pin;input.value=k==='clear'?'':k==='back'?input.value.slice(0,-1):(input.value+k).slice(0,64)});$('#login').onsubmit=async e=>{e.preventDefault();const b=$('#login button[type=submit]');if(b.disabled)return;b.disabled=true;document.querySelectorAll('[data-pin]').forEach(k=>k.disabled=true);try{let session;if(invite)session=await api('/shooting/redeem',{token:$('#credential').value});else{const a=await api('/admin/login',{pin:$('#credential').value});session=await api('/shooting/owner-session?x_admin_token='+encodeURIComponent(a.token),{});}
 await openAccount(session);if(invite&&!standalone())setTimeout(()=>notify('Открой «Съёмки» в Safari и добавь на экран «Домой» — так вход не слетит'),800);}catch(e){$('#login-error').textContent=e.message+(invite&&e.status===403?'. Если уже входил на этом телефоне — выбери аккаунт ниже или войди по PIN.':'')}finally{b.disabled=false;document.querySelectorAll('[data-pin]').forEach(k=>k.disabled=false)}};}
function shootSteps(c){return [{id:'slate',block:'Код ролика',text:`${c.spoken_code||c.code}\n\nПроизнеси код и хлопни в ладоши.`,filmed:c.slate},...variants(c).sort((a,b)=>Number(b.block==='Заметки себе')-Number(a.block==='Заметки себе'))];}
function renderShoot(){const d=item(shoot.day),r=item(shoot.ids[shoot.card]);if(!r){shoot=null;view='day';selected=d.id;render();return}const steps=shootSteps(r.data);shoot.step=Math.min(shoot.step,steps.length-1);saveResume();const s=steps[shoot.step],total=cards(d.id),done=total.filter(x=>complete(x.data)).length;$('#app').innerHTML=`<main class="shoot"><div class="row between"><div class="row narrow">${btn('Выйти','exit-shoot')}${can('takes')?btn(icon('retake')+'<span>Ещё дубль</span>','shoot-take','with-icon'):''}</div><span class="pill">${esc(d.data.title)} · ${done}/${total.length} снято</span></div><progress max="${total.length||1}" value="${done}"></progress><div class="row between"><span class="code">${esc(r.data.spoken_code||r.data.code)}</span><span class="muted">${shoot.step+1}/${steps.length}</span></div><p class="eyebrow">${esc(s.block)}${s.filmed?' · уже снято':''}</p><div class="speech-deck">${shoot.step>0?`<div class="speech-neighbor neighbor-prev" aria-hidden="true">${esc(steps[shoot.step-1].text)}</div>`:''}<div class="speech ${s.filmed?'done':''}" id="speech">${esc(s.text)}</div>${shoot.step<steps.length-1?`<div class="speech-neighbor neighbor-next" aria-hidden="true">${esc(steps[shoot.step+1].text)}</div>`:''}</div>${s.block==='Заметки себе'?'<p class="muted">Подсказка для тебя. Не входит в прогресс съёмки.</p>':''}<div class="controls">${ib('left','Вернуться к предыдущей фразе','shoot-back',shoot.step?'':'disabled')}${btn(icon('check')+(s.block==='Заметки себе'?' Дальше':' Снято'),'shoot-next','green')}</div><p class="muted">Свайп влево — дальше · вправо — назад</p><div class="sync"></div></main>`;status();window.scrollTo(0,0);swipe($('#speech'),()=>dispatch('shoot-next',{}),()=>dispatch('shoot-back',{}));}
function takeLabel(r){const rootId=r.data.take_of||r.id,root=item(rootId)||r,base=(root.data.spoken_code||root.data.code).split(', дубль ')[0],n=Math.max(root.data.take||1,...state.items.filter(i=>i.kind==='card'&&i.data.take_of===rootId).map(i=>i.data.take||1))+1;return {rootId,n,label:base+', дубль '+n}}
async function makeTake(r){const c=r.data,{rootId,n,label}=takeLabel(r),day=c.day_id,later=cards(day||undefined).map(x=>x.data.order).filter(o=>o>c.order),order=later.length?(c.order+Math.min(...later))/2:c.order+1;
 const data={...copy(c),code:localCode(),spoken_code:label,take_of:rootId,take:n,order,slate:false,archived:false,blocks:c.blocks.map(b=>({id:uid(),title:b.title,variants:b.variants.map(v=>({...v,id:uid(),filmed:false}))})),details:{...copy(c.details),filmed_at:'',raw_files:'',color:false,edit:false,subtitles:false,platforms:{}}};
 return add('card',data);}
function newCard(text,hypothesis_id=''){return {title:text.slice(0,150),idea:text,code:localCode(),source_id:'',source_title:'',source_quote:'',timecode:'',day_id:'',order:Date.now(),slate:false,blocks:['Заметки себе','Хуки','Интрига','Тема','Призыв'].map(title=>({id:uid(),title,variants:[]})),details:{filmed_at:'',raw_files:'',notes:'',color:false,edit:false,subtitles:false,platforms:{}},archived:false,...(hypothesis_id?{hypothesis_id}:{})}}
// Hypotheses: an approach to test; its themes are ordinary cards of the idea bank tied by hypothesis_id.
function hyps(all=false){return state.items.filter(i=>i.kind==='hypothesis'&&(all||!i.data.archived)).sort((a,b)=>(b.data.order||0)-(a.data.order||0))}
function themes(hid){return state.items.filter(i=>i.kind==='card'&&!i.data.archived&&i.data.hypothesis_id===hid).sort((a,b)=>a.data.order-b.data.order)}
function hypName(c){const h=c.hypothesis_id&&item(c.hypothesis_id);return h&&h.kind==='hypothesis'?h.data.title:''}
function hypFilter(){const h=ideaView.hyp||'';return h==='-'||item(h)?.kind==='hypothesis'?h:''}
function hypSelect(){if(!can('hypotheses')||!hyps().length)return '';const h=hypFilter();return `<select id="idea-hyp" class="idea-sort idea-hyp" aria-label="Гипотеза"><option value="">Все гипотезы</option><option value="-" ${h==='-'?'selected':''}>Без гипотезы</option>${hyps().map(x=>`<option value="${x.id}" ${h===x.id?'selected':''}>${esc(x.data.title)}</option>`).join('')}</select>`}
function shortUrl(u){try{const x=new URL(u);return (x.hostname.replace(/^www\./,'')+x.pathname).replace(/\/$/,'')}catch{return u}}
function themeRow(r){const c=r.data,s=stage(c),[w,f,p,g]=progress(c);return `<button class="theme-row" data-action="theme-open" data-id="${r.id}"><span class="theme-line"><span class="code">${esc(c.spoken_code||c.code)}</span><span class="theme-title">${esc(c.title)}</span></span><span class="theme-line"><span class="theme-stage stage-${s}">${STAGES.find(x=>x[0]===s)[1]}</span><span class="mini-bars" aria-label="Написание ${Math.round(w*100)}%, съёмка ${Math.round(f*100)}%, постпрод ${Math.round(p*100)}%, постинг ${Math.round(g*100)}%">${[w,f,p,g].map(v=>`<i style="--v:${v}"></i>`).join('')}</span></span></button>`}
function refreshThemes(){$('#themes').innerHTML=themeList();$('#theme-count').textContent=themes(hypo).length}
function themeList(){const list=themes(hypo);return list.map(themeRow).join('')||'<p class="muted">Тем пока нет. Напиши первую — она сразу появится в банке идей.</p>'}
function hypTile(r){const h=r.data,t=themes(r.id),done=t.filter(x=>complete(x.data)).length;return `<article class="card hyp-card">${btn(`<h3>${esc(h.title)}</h3>`,'hyp-open','open',`data-id="${r.id}"`)}${h.description?`<p class="hyp-desc">${esc(h.description)}</p>`:''}<p class="muted">${h.refs.length} реф. · ${t.length} тем · ${done} снято</p>${h.archived?btn('Вернуть','hyp-unarchive','',`data-id="${r.id}"`):btn('Открыть','hyp-open','',`data-id="${r.id}"`)}</article>`}
function renderHypotheses(){const archivedHyps=hyps(true).filter(x=>x.data.archived);return `<div class="eyebrow">Проверка подходов</div><div class="row between"><h1>Гипотезы</h1>${btn('Новая гипотеза','new-hyp','primary')}</div><p class="muted">Подход к контенту, который хочешь проверить: референсы с пометками и темы, которые сразу попадают в банк идей.</p><div class="grid" style="margin-top:20px">${hyps().map(hypTile).join('')||'<div class="empty">Первая гипотеза — например, «Широкий заход, узкая перспектива».</div>'}</div>${archivedHyps.length?`<details class="hyp-archive"><summary>Архив гипотез · ${archivedHyps.length}</summary><div class="grid">${archivedHyps.map(hypTile).join('')}</div></details>`:''}`}
function renderHypothesis(){const h=item(hypo).data;return `${btn('Все гипотезы','nav','','data-view="hypotheses"')}<div class="eyebrow" style="margin-top:22px">Гипотеза</div><div class="row between hyp-head"><h1>${esc(h.title)}</h1><div class="tools">${ib('edit','Название и описание','edit-hyp')}${ib('archive','Убрать в архив','hyp-archive')}</div></div>${h.description?`<p class="hyp-text">${esc(h.description)}</p>`:btn('Добавить описание','edit-hyp','quiet')}<section class="panel hyp-section"><div class="row between"><h2>Референсы</h2>${ib('plus','Добавить референс','ref-add')}</div>${h.refs.map((x,i)=>`<div class="ref"><div class="row between ref-head"><a class="ref-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${icon('link')}<span>${i+1}. ${esc(shortUrl(x.url))}</span></a><div class="tools">${ib('edit','Изменить референс','ref-edit',`data-ref="${x.id}"`)}${ib('trash','Удалить референс','ref-del',`data-ref="${x.id}"`)}</div></div>${x.comment?`<p class="ref-comment">${esc(x.comment)}</p>`:''}</div>`).join('')||'<p class="muted">Добавь ссылку на ролик-образец и пометь, какой там хук и какая тема.</p>'}</section><section class="panel hyp-section"><div class="row between"><h2>Темы</h2><span class="muted" id="theme-count">${themes(hypo).length}</span></div><form class="theme-add" id="theme-add"><input id="theme-input" maxlength="12000" placeholder="Новая тема — и Enter" aria-label="Новая тема" autocomplete="off" enterkeyhint="done">${ib('plus','Добавить тему','noop','type="submit"')}</form><div class="theme-list" id="themes">${themeList()}</div></section>`}
// Independent copy: own frame number from the server, no link to the original's takes.
async function copyCard(r){const c=r.data,data={...copy(c),title:(c.title+' · копия').slice(0,150),code:localCode(),order:Date.now(),slate:false,archived:false,blocks:c.blocks.map(b=>({id:uid(),title:b.title,variants:b.variants.map(v=>({...v,id:uid(),filmed:false}))})),details:{...copy(c.details),filmed_at:'',raw_files:'',color:false,edit:false,subtitles:false,platforms:{}}};delete data.spoken_code;delete data.take_of;delete data.take;return add('card',data);}
async function nextPhrase(){const r=item(shoot.ids[shoot.card]),steps=shootSteps(r.data),s=steps[shoot.step];await change(r.id,c=>{if(s.id==='slate')c.slate=true;else for(const b of c.blocks)for(const v of b.variants)if(v.id===s.id&&b.title!=='Заметки себе')v.filmed=true;if(complete(c)&&!c.details.filmed_at)c.details.filmed_at=new Date().toLocaleDateString('sv-SE')});const upcoming=shootSteps(r.data).findIndex((v,i)=>i>shoot.step&&!v.filmed);if(upcoming>=0){shoot.step=upcoming;render();return}const isDone=complete(r.data);modal(`<h1>${isDone?'Снято':'Пока нет фраз для съёмки'}</h1><p>${esc(r.data.title)}</p><p class="muted">${isDone?'Отметки сохранены на устройстве.':'Добавь варианты в сценарий. Код и заметки не считаются снятым роликом.'}</p><div class="row modal-actions">${btn(shoot.card+1<shoot.ids.length?'Следующая карточка':'Завершить день','shoot-card','primary')}${can('takes')?btn(icon('retake')+'<span>Ещё дубль</span>','shoot-take','with-icon'):''}</div>`);}
function swipe(el,left,right){let start,axis;const deck=el.parentElement;el.onpointerdown=e=>{if(e.button&&e.button!==0)return;start={x:e.clientX,y:e.clientY};axis='';deck.style.transition='none';};el.onpointermove=e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(!axis&&Math.max(Math.abs(dx),Math.abs(dy))>8)axis=Math.abs(dx)>Math.abs(dy)?'x':'y';if(axis==='x'){el.setPointerCapture?.(e.pointerId);const canMove=dx<0?deck.querySelector('.neighbor-next'):deck.querySelector('.neighbor-prev');deck.style.setProperty('--drag',Math.max(-el.clientWidth,Math.min(el.clientWidth,dx*(canMove?1:.2)))+'px')}};const reset=()=>{deck.style.setProperty('--drag','0px');start=null;axis=''};el.onpointerup=e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;reset();if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.5)(dx<0?left:right)()};el.onpointercancel=reset;}
function bindSwipes(){document.querySelectorAll('[data-rail]').forEach(rail=>{const bid=rail.dataset.rail;const update=()=>{const pages=[...rail.children];const center=rail.scrollLeft+rail.clientWidth/2;let ix=0;pages.forEach((p,i)=>{if(Math.abs(p.offsetLeft+p.offsetWidth/2-center)<Math.abs(pages[ix].offsetLeft+pages[ix].offsetWidth/2-center))ix=i});indices[bid]=ix;const root=rail.closest('.block');root.querySelector('.variant-count').textContent=(ix+1)+' / '+pages.length;root.querySelector('[data-dir="-1"]').disabled=ix===0;root.querySelector('[data-dir="1"]').disabled=ix===pages.length-1;};rail.addEventListener('scroll',update,{passive:true});const page=rail.children[indices[bid]||0];if(page)rail.scrollLeft=page.offsetLeft-(rail.clientWidth-page.offsetWidth)/2;update()})}
function moveVariant(bid,dir){const rail=[...document.querySelectorAll('[data-rail]')].find(el=>el.dataset.rail===bid);if(!rail)return;const ix=Math.max(0,Math.min(rail.children.length-1,(indices[bid]||0)+dir)),page=rail.children[ix];rail.scrollTo({left:page.offsetLeft-(rail.clientWidth-page.offsetWidth)/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
async function fill(mode){if(state.dirty.includes(selected)){await sync();if(state.dirty.includes(selected))throw Error('Сначала нужна синхронизация карточки')}notify('Готовим варианты. Существующий текст сохраняется.');const id=selected,res=await api('/shooting/items/'+id+'/suggest',{mode});const d=modal(`<h2>${mode==='quote'?'Цитаты из лекции':'Черновики ИИ'}</h2><p class="muted">Варианты добавятся к существующим и будут ждать твоей проверки.</p>${res.blocks.map(b=>`<h3>${esc(b.title)}</h3>${b.texts.map(t=>`<p>${esc(t)}</p>`).join('')}`).join('')}<div class="row">${btn('Добавить варианты','noop','primary','id="accept-fill"')}${btn('Отмена','close')}</div>`);$('#accept-fill').onclick=async()=>{await change(id,c=>{for(const b of res.blocks){let target=c.blocks.find(x=>x.title===b.title);if(!target){target={id:uid(),title:b.title,variants:[]};c.blocks.push(target)}for(const text of b.texts)if(!target.variants.some(v=>v.text===text))target.variants.push({id:uid(),text,origin:mode,reviewed:false,filmed:false})}});d.remove();render()};}
async function act(action,d){const r=item(),b=r?.data.blocks?.find(b=>b.id===d.block),v=b?.variants.find(x=>x.id===d.variant)||b?.variants[indices[b.id]||0];
 switch(action){
 case 'export-script':exportScript(r);return;
 case 'undo-card':case 'redo-card':{const h=state.history?.[r.id],from=action==='undo-card'?'undo':'redo',to=from==='undo'?'redo':'undo';if(!h?.[from].length)return;if(Object.values(state.drafts||{}).some(x=>x.card===r.id)&&!confirm('Отменить несохранённые правки текста и перейти к версии карточки?'))return;for(const key of Object.keys(state.drafts||{}))if(state.drafts[key].card===r.id)delete state.drafts[key];const next=h[from].pop();h[to].push({data:copy(r.data),drafts:copy(Object.values(state.drafts||{}).filter(d=>d.card===r.id))});await change(r.id,c=>{for(const key of Object.keys(c))delete c[key];Object.assign(c,next.data||next);state.drafts??={};for(const draft of next.drafts||[])state.drafts[draft.card+':'+draft.block+':'+draft.variant]=draft},false);return;}
 case 'reset-card':{if(!confirm('Очистить сценарий, отметки съёмки, постпрод, ссылки на публикации и съёмочный день? Идея, название и код останутся. Сброс можно отменить.'))return;await change(r.id,c=>{c.blocks=['Заметки себе','Хуки','Интрига','Тема','Призыв'].map(title=>({id:uid(),title,variants:[]}));c.slate=false;c.day_id='';c.details={filmed_at:'',raw_files:'',notes:'',color:false,edit:false,subtitles:false,platforms:{}};for(const key of Object.keys(state.drafts||{}))if(state.drafts[key].card===r.id)delete state.drafts[key]});return;}
 case 'idea-filter':{const k=d.key;ideaView.show={...ideaView.show,[k]:ideaView.show[k]===false};writeLocal(VIEW_KEY,ideaView);render();return;}
 case 'theme':writeLocal(THEME_KEY,d.themePick);applyTheme();render();return;
 case 'duplicate':{const take=can('takes')?takeLabel(r):null;modal(`<h2>Дублировать карточку</h2><p class="muted">Сценарий копируется целиком, отметки съёмки и постпрода — нет.</p><div class="row">${take?btn('Ещё дубль · '+esc(take.label),'dup-take'):''}${btn('Копия как новая идея','dup-copy')}${btn('Отмена','close','quiet')}</div>`);return;}
 case 'dup-take':{document.querySelector('dialog')?.remove();selected=await makeTake(r);if(!sheet)view='card';tab='script';render();notify('Новая карточка: '+item(selected).data.spoken_code);return;}
 case 'dup-copy':{document.querySelector('dialog')?.remove();selected=await copyCard(r);if(!sheet)view='card';tab='script';render();notify('Копия создана — номер кадра выдаст сервер');return;}
 case 'accounts':modal(`<h2>Аккаунты на этом устройстве</h2><div class="account-list">${accounts.map(a=>{const on=state.session&&a.key===accountKey(state.session);return btn(`<span>${esc(accountLabel(a.session))}</span>${on?'<span class="pill">Сейчас</span>':''}`,on?'close':'switch-account',on?'active':'',`data-key="${esc(a.key)}"`)}).join('')}</div><p class="muted">Добавить — войти по PIN владельца или по новой ссылке-приглашению.${state.session?.role==='owner'?' В профили, которые ты создал, можно войти из «Списка доступов».':''}</p><div class="row">${btn('Добавить аккаунт','add-account','primary')}${btn('Закрыть','close')}</div>`);return;
 case 'switch-account':document.querySelector('dialog')?.remove();await switchAccount(d.key);notify(accountLabel(state.session));return;
 case 'add-account':document.querySelector('dialog')?.remove();renderLogin();return;
 case 'login-cancel':loginOpen=false;pendingInvite='';render();return;
 case 'login-pin':pendingInvite='';renderLogin();return;
 case 'visit':{const s=await api('/shooting/access/'+d.id+'/visit',{});await openAccount(s);notify(`Ты в профиле «${s.name}». Вернуться к своим сценариям — кнопка аккаунта вверху.`);return;}
 case 'resume-shoot':{const p=resumePoint();if(p)await startShoot(p.day,p.card,p.step);return;}
 case 'resume-hide':resumeHidden=true;render();return;
 case 'shoot-day':await startShoot(d.id);return;
 case 'x-variant':{const exists=b?.variants.find(x=>x.id===d.variant);if(!exists){delete state.drafts?.[draftKey(b.id,d.variant)];await persist();render();return}if(confirm('Удалить этот вариант?'))await change(r.id,c=>{const target=c.blocks.find(x=>x.id===b.id);target.variants=target.variants.filter(x=>x.id!==d.variant);delete state.drafts?.[draftKey(b.id,d.variant)]});return;}
 case 'theme-open':selected=d.id;sheet=true;tab='script';render();return;
 case 'sheet-close':sheet=false;selected='';render();return;
 case 'new-hyp':editor('Название гипотезы','',async title=>{hypo=await add('hypothesis',{title,description:'',refs:[],archived:false,order:Date.now()});view='hypothesis'},false);return;
 case 'hyp-open':hypo=d.id;view='hypothesis';sheet=false;render();return;
 case 'edit-hyp':{const h=item(hypo);const dlg=modal(`<h2>Гипотеза</h2><form><label>Название<input name="title" required maxlength="500" value="${esc(h.data.title)}"></label><label>Описание<textarea name="description" maxlength="12000" placeholder="Что проверяем и почему">${esc(h.data.description)}</textarea></label><div class="row">${ib('save','Сохранить','noop','type="submit"')}${btn('Отмена','close','','type="button"')}</div></form>`);dlg.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')).trim();if(!title)return;dlg.remove();await change(hypo,x=>{x.title=title;x.description=String(f.get('description')).trim()})};return;}
 case 'ref-add':case 'ref-edit':{const h=item(hypo),ref=h.data.refs.find(x=>x.id===d.ref)||{url:'',comment:''};const dlg=modal(`<h2>${d.ref?'Референс':'Новый референс'}</h2><form><label>Ссылка на видео<input name="url" type="url" inputmode="url" required maxlength="2000" placeholder="https://www.instagram.com/reel/…" value="${esc(ref.url)}"></label><label>Комментарий<textarea name="comment" maxlength="4000" placeholder="Какой хук, какая тема, что взять">${esc(ref.comment)}</textarea></label><div class="row">${ib('save','Сохранить','noop','type="submit"')}${btn('Отмена','close','','type="button"')}</div></form>`);dlg.querySelector('[name=url]').focus({preventScroll:true});dlg.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),url=String(f.get('url')).trim(),comment=String(f.get('comment')).trim();if(!/^https?:\/\/\S+$/.test(url)){notify('Ссылка должна начинаться с https://');return}dlg.remove();await change(hypo,x=>{const i=x.refs.findIndex(y=>y.id===d.ref);if(i>=0)x.refs[i]={...x.refs[i],url,comment};else x.refs.push({id:uid(),url,comment})})};return;}
 case 'ref-del':if(confirm('Удалить этот референс?'))await change(hypo,x=>{x.refs=x.refs.filter(y=>y.id!==d.ref)});return;
 case 'hyp-archive':if(confirm('Убрать гипотезу в архив? Её темы останутся в банке идей.')){await change(hypo,x=>x.archived=true);view='hypotheses';render()}return;
 case 'hyp-unarchive':await change(d.id,x=>x.archived=false);return;
 case 'reset-shoot':{if(!confirm('Снять все отметки съёмки с этой карточки? Сценарий останется. Отменить можно стрелкой назад.'))return;await change(r.id,c=>{c.slate=false;c.details.filmed_at='';for(const b of c.blocks)for(const x of b.variants)x.filmed=false});notify('Отметки съёмки сняты');return;}
 case 'archive':await change(d.id,c=>c.archived=true);notify('Убрано в архив. Вернуть — во вкладке «Архив»');return;
 case 'unarchive':await change(d.id,c=>c.archived=false);notify('Идея вернулась в банк');return;
 case 'idea-archive':ideaView.archive=!ideaView.archive;writeLocal(VIEW_KEY,ideaView);render();return;
 case 'new-profile':editor('Как назвать профиль','',async name=>{const p=await api('/shooting/profiles',{name});setTimeout(()=>modal(`<h2>Профиль «${esc(p.name)}» готов</h2><p>Открой эту ссылку на телефоне, где будет профиль. Она сработает один раз и действует 7 дней. В профиле свои идеи, сценарии и съёмочные дни — твоих там не видно, а тебе не видно его.</p>${linkBox(new URL('./',location.href).href+'#invite='+p.token)}${btn('Закрыть','close')}`),0)},false);return;
 case 'noop':return;case 'sync':await sync();return;case 'close':document.querySelector('dialog')?.remove();return;
 case 'nav':view=d.view;selected='';sheet=false;render();return;case 'open':selected=d.id;view='card';sheet=false;tab='script';render();return;case 'day':selected=d.id;view='day';render();return;case 'tab':tab=d.tab;render();return;
 case 'new-card':editor('Идея','',async text=>{const h=hypFilter();selected=await add('card',newCard(text,h&&h!=='-'?h:''));view='card';tab='script'});return;
 case 'new-day':editor('Название дня','День '+(days().length+1),async title=>{selected=await add('day',{title,date:'',archived:false});view='day'},false);return;
 case 'edit-day':{const dlg=modal(`<h2>Съёмочный день</h2><form><label>Название<input name="title" required value="${esc(r.data.title)}"></label><label>Дата<input name="date" type="date" value="${esc(r.data.date)}"></label><button class="primary">Сохранить</button>${btn('Отмена','close','','type="button"')}</form>`);dlg.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await change(r.id,c=>{c.title=f.get('title');c.date=f.get('date')});dlg.remove();render()};return;}
 case 'edit-idea':editor('Идея',r.data.idea,text=>change(r.id,c=>{c.idea=text;c.title=text.slice(0,150)}));return;
 case 'add-block':editor('Название блока','',title=>change(r.id,c=>c.blocks.push({id:uid(),title,variants:[]})),false);return;
 case 'block-up':await change(r.id,c=>{const i=c.blocks.findIndex(x=>x.id===b.id);if(i>0)[c.blocks[i-1],c.blocks[i]]=[c.blocks[i],c.blocks[i-1]]});return;
 case 'del-block':if(confirm('Удалить блок и все его варианты?'))await change(r.id,c=>{c.blocks=c.blocks.filter(x=>x.id!==b.id);for(const key of Object.keys(state.drafts||{}))if(state.drafts[key].card===r.id&&state.drafts[key].block===b.id)delete state.drafts[key]});return;
 case 'variant':moveVariant(b.id,Number(d.dir));return;
 case 'add-variant':case 'edit-variant':{const id=uid();state.drafts??={};state.drafts[draftKey(b.id,id)]={card:selected,block:b.id,variant:id,text:'',isNew:true};indices[b.id]=blockVariants(b).length-1;await persist();render();return;}
 case 'save-variant':{const key=draftKey(b.id,d.variant),draft=state.drafts?.[key];if(!draft)return;const text=draft.text.trim();if(!text){notify('Напиши текст или отмени пустой вариант');return}delete state.drafts[key];await change(r.id,c=>{const target=c.blocks.find(x=>x.id===b.id),t=target.variants.find(x=>x.id===d.variant);if(t){if(t.text!==text){t.text=text;t.filmed=false;t.reviewed=t.origin==='manual'}}else target.variants.push({id:d.variant,text,origin:'manual',reviewed:true,filmed:false})});return;}
 case 'cancel-variant':delete state.drafts?.[draftKey(b.id,d.variant)];await persist();render();return;
 case 'del-variant':if(!v)return;if(confirm('Удалить этот вариант?'))await change(r.id,c=>{const target=c.blocks.find(x=>x.id===b.id);target.variants=target.variants.filter(x=>x.id!==v.id);delete state.drafts?.[draftKey(b.id,v.id)]});return;
 case 'review':await change(r.id,c=>c.blocks.find(x=>x.id===b.id).variants.find(x=>x.id===v.id).reviewed=true);return;
 case 'fill':await fill(d.mode);return;
 case 'assign':{const day=selected;modal(`<h2>Добавить в ${esc(r.data.title)}</h2><p class="muted">Выбор переместит карточку из другого дня, если она уже назначена.</p>${cards().filter(c=>c.data.day_id!==day).map(c=>`<div class="panel"><h3>${esc(c.data.title)}</h3>${btn('Добавить в день','assign-card','','data-id="'+c.id+'" data-day="'+day+'"')}</div>`).join('')||'<p>Все идеи уже в этом дне.</p>'}${btn('Готово','close')}`);return;}
 case 'assign-card':await change(d.id,c=>{c.day_id=d.day;c.order=Date.now()});document.querySelector('dialog')?.remove();render();return;
 case 'reorder':{const list=cards(r.id),i=list.findIndex(c=>c.id===d.id),j=i+Number(d.dir);if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];for(let n=0;n<list.length;n++)await change(list[n].id,c=>c.order=n);return;}
 case 'shoot':await startShoot(selected);return;
 case 'shoot-take':{document.querySelector('dialog')?.remove();const r=item(shoot.ids[shoot.card]);if(!r)return;const id=await makeTake(r);shoot.ids.splice(shoot.card+1,0,id);shoot.card++;shoot.step=0;notify('Новая карточка: '+item(id).data.spoken_code);render();return;}
 case 'shoot-back':if(shoot.step>0)shoot.step--;render();return;case 'shoot-next':await nextPhrase();return;
 case 'shoot-card':document.querySelector('dialog')?.remove();if(shoot.card+1<shoot.ids.length){shoot.card++;const next=shootSteps(item(shoot.ids[shoot.card]).data);shoot.step=Math.max(0,next.findIndex(s=>!s.filmed));render()}else{selected=shoot.day;shoot=null;void wakeLock?.release();wakeLock=null;view='day';render()}return;
 case 'exit-shoot':selected=shoot.day;shoot=null;void wakeLock?.release();wakeLock=null;view='day';render();return;
 case 'invite':editor('Кому доступ — имя','',async name=>{const invite=await api('/shooting/invites',{name});setTimeout(()=>modal(`<h2>Приглашение готово</h2><p>Передай ссылку лично монтажёру. Она сработает один раз.</p>${linkBox(new URL('./',location.href).href+'#invite='+invite.token)}${btn('Закрыть','close')}`),0)},false);return;
 case 'members':{const members=await api('/shooting/access');$('#members').innerHTML=members.map(m=>`<p>${esc(m.name)} · ${m.revoked?'Отозван':{invite:'Монтажёр, ожидает входа',invite_author:'Профиль, ожидает входа',author:'Отдельный профиль'}[m.role]||'Монтажёр'} ${!m.revoked&&m.role==='author'&&can('visits')?btn('Войти','visit','','data-id="'+m.id+'"'):''}${!m.revoked?btn('Отозвать','revoke','','data-id="'+m.id+'"'):''}</p>`).join('');return;}
 case 'revoke':if(confirm('Отозвать доступ к серверу?')){await api('/shooting/access/'+d.id,undefined,'DELETE');await act('members',{})}return;
 case 'logout':{if(state.dirty.length){notify('Сначала синхронизируй изменения и разбери конфликты.');return}if(!confirm('Выйти из этого аккаунта на этом устройстве? Его сценарии на телефоне удалятся, на сервере останутся.'))return;const key=accountKey(state.session);accounts=accounts.filter(a=>a.key!==key);await idbDel('ws:'+key);const next=accounts[0];state={session:null,items:[],dirty:[],conflicts:{}};if(next){await openAccount(next.session,await idbGet('ws:'+next.key))}else{await persist();await idbPut('accounts',[]);view='ideas';render()}return;}
 case 'reauth':renderLogin();return;
 case 'conflicts':{const id=Object.keys(state.conflicts)[0],local=item(id),remote=state.conflicts[id];modal(`<div class="conflict"><h2>Две версии: ${esc(local.data.title)}</h2><p>Серверную версию оставим на месте. Твои изменения сохраним отдельной карточкой с новым кодом, чтобы можно было спокойно сравнить.</p><h3>На устройстве</h3><pre>${esc(JSON.stringify(local.data,null,2))}</pre><h3>На сервере</h3><pre>${esc(JSON.stringify(remote.data||remote,null,2))}</pre>${btn('Сохранить обе версии','fork-conflict','primary','data-id="'+id+'"')}${btn('Позже','close')}</div>`);return;}
 case 'fork-conflict':{const local=item(d.id),remote=await api('/shooting/workspace'),server=remote.items.find(x=>x.id===d.id);if(!server)throw Error('Серверная версия не найдена');const fork=copy(local.data),id=uid();fork.title+=' · моя версия';if(local.kind==='card'){fork.code=localCode();delete fork.spoken_code;fork.slate=false;}Object.assign(local,server);state.dirty=state.dirty.filter(x=>x!==d.id);delete state.conflicts[d.id];await add(local.kind,fork,id);document.querySelector('dialog')?.remove();render();return;}
 }}
let actionChain=Promise.resolve();
function dispatch(action,data){if(busy&&action.startsWith('shoot'))return;const args={...data},run=async()=>{busy=true;try{await act(action,args)}catch(err){notify(err.message)}finally{busy=false}};actionChain=busy?actionChain.then(run):run();return actionChain}
// Invite links: a tap copies. Runs inside the click itself — Safari allows the clipboard only there.
function linkBox(url){return `<button type="button" class="invite-link" data-copy-link>${esc(url)}</button><p class="copy-state muted" aria-live="polite">Нажми на ссылку — она скопируется</p><p class="muted">Пусть откроет её в Safari и добавит «Съёмки» на экран «Домой». Во встроенном браузере Telegram вход может слететь.</p>`}
async function copyLink(box){const text=box.querySelector('.invite-link').textContent,state=box.querySelector('.copy-state');let ok=false;
 try{await navigator.clipboard.writeText(text);ok=true}catch{const t=document.createElement('textarea');t.value=text;t.setAttribute('readonly','');t.style.cssText='position:fixed;opacity:0;top:0;left:0';box.append(t);t.select();try{ok=document.execCommand('copy')}catch{}t.remove()}
 getSelection()?.removeAllRanges();state.textContent=ok?'Скопировано ✓ — вставь ссылку в сообщение':'Не получилось скопировать — нажми на ссылку ещё раз'}
document.addEventListener('click',e=>{const link=e.target.closest('[data-copy-link]');if(link){void copyLink(link.closest('dialog'));return}const target=e.target.closest('[data-action]');if(target&&!target.disabled)void dispatch(target.dataset.action,target.dataset)});
document.addEventListener('input',e=>{const t=e.target;if(!t.dataset.inlineBlock)return;fitText(t);state.drafts??={};state.drafts[draftKey(t.dataset.inlineBlock,t.dataset.inlineVariant)]={card:selected,block:t.dataset.inlineBlock,variant:t.dataset.inlineVariant,text:t.value,isNew:t.dataset.new==='1'};t.closest('.variant-page').querySelector('.draft-status').textContent='Черновик на устройстве';void persist().catch(()=>notify('Не удалось сохранить черновик на устройстве'))});
document.addEventListener('change',async e=>{const t=e.target;if(!(view==='card'||sheet)||!item()||t.closest('dialog'))return;try{if(t.dataset.field)await change(selected,c=>c[t.dataset.field]=t.value);if(t.dataset.detail)await change(selected,c=>c.details[t.dataset.detail]=t.type==='checkbox'?t.checked:t.value);if(t.dataset.platform)await change(selected,c=>{if(t.checked)c.details.platforms[t.dataset.platform]='';else delete c.details.platforms[t.dataset.platform]});if(t.dataset.link){if(t.value&&!/^https?:\/\//.test(t.value)){notify('Ссылка должна начинаться с https://');return}await change(selected,c=>c.details.platforms[t.dataset.link]=t.value)}}catch(err){notify('Не удалось сохранить: '+err.message)}});
// iOS ignores user-scalable=no: block the pinch gesture itself.
for(const t of ['gesturestart','gesturechange'])document.addEventListener(t,e=>e.preventDefault(),{passive:false});document.addEventListener('touchmove',e=>{if(e.touches.length>1)e.preventDefault()},{passive:false});
window.addEventListener('online',()=>void sync());window.addEventListener('offline',()=>{message='Без интернета · изменения на устройстве';status()});
try{await openDB();if(new URLSearchParams(location.hash.slice(1)).has('invite')&&state.session)renderLogin();else render();await sync();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>notify('Офлайн-режим пока недоступен'));setInterval(()=>void sync(),30000);}catch(e){$('#app').innerHTML='<main class="login"><h1>Не удалось открыть хранилище</h1><p>Разреши сохранение данных сайта и открой приложение снова. В приватном режиме офлайн-работа может быть недоступна.</p></main>';console.error(e)}

function fitKeyboard(){document.documentElement.style.setProperty('--keyboard-height',`${window.visualViewport?.height||innerHeight}px`)}
window.visualViewport?.addEventListener('resize',fitKeyboard);fitKeyboard();
document.addEventListener('submit',async e=>{if(e.target.id!=='theme-add')return;e.preventDefault();const input=$('#theme-input'),text=input.value.trim();if(!text||!item(hypo))return;input.value='';await add('card',newCard(text,hypo));refreshThemes();input.focus({preventScroll:true})});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sheet&&!document.querySelector('dialog[open]')){sheet=false;selected='';render()}});
['focusin','focusout'].forEach(n=>document.addEventListener(n,e=>{if(e.target.classList?.contains('inline-phrase'))requestAnimationFrame(()=>fitText(e.target))}));addEventListener('resize',fitTexts);
